def match_branch_company_collation(apps, schema_editor):
    """ตาราง BaseBranchCompany เดิม collation ไม่ตรงกับค่า default ของ database (import มาจาก MariaDB)
    ต้องปรับตารางใหม่ให้ตรงกันก่อน ไม่งั้น MySQL สร้าง FK -> BaseBranchCompany.id ไม่ได้ (error 3780) ดู 0147"""
    if schema_editor.connection.vendor != 'mysql':
        return
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(
            "SELECT CHARACTER_SET_NAME, COLLATION_NAME FROM information_schema.COLUMNS "
            "WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'BaseBranchCompany' AND COLUMN_NAME = 'id'"
        )
        row = cursor.fetchone()
    if row:
        schema_editor.execute("ALTER TABLE `BaseVendorOrigin` CONVERT TO CHARACTER SET %s COLLATE %s" % row)


def add_origins(apps, schema_editor):
    BaseVendorOrigin = apps.get_model("stock", "BaseVendorOrigin")
    BaseBranchCompany = apps.get_model("stock", "BaseBranchCompany")
    for order, (name, address, map_url, coordinates, branch_name) in enumerate(ORIGINS, start=1):
        lat, lng = coordinates.split(",")
        branch = BaseBranchCompany.objects.filter(name=branch_name).first() if branch_name else None
        BaseVendorOrigin.objects.get_or_create(name=name, defaults={
            "address": address,
            "map_url": map_url,
            "latitude": _six(lat),
            "longitude": _six(lng),
            "branch_company": branch,
            "order": order,
        })


